// Normaliza la respuesta de la RPC a un item por conversación.
let rows;
const all = $input.all();
if (all.length > 1) {
  rows = all.map(i => i.json);
} else {
  const j = all[0]?.json;
  rows = Array.isArray(j) ? j : (Array.isArray(j?.data) ? j.data : (j?.id ? [j] : []));
}
return rows.map(r => ({ json: { id: r.id, messages: r.messages } }));

const msgs = Array.isArray($json.messages) ? $json.messages : [];
const transcript = msgs
  .map(m => `${m.role === 'user' ? 'Usuario' : 'Bot'}: ${String(m.content ?? '').trim()}`)
  .join('\n')
  .slice(0, 4000);
return { json: { id: $json.id, transcript } };

const raw = $json.choices?.[0]?.message?.content ?? '{}';
const e = JSON.parse(raw);
const id = $('Construir prompt').item.json.id;
return { json: {
  id,
  resolution_status: e.resolution_status,
  category: e.category,
  knowledge_gap: e.knowledge_gap,
  summary: e.summary,
  sentiment: e.sentiment,
} };
